    i1 = _auxmtx_req;
    r9 = AUXMTX_N;
.amp_req:
    r0 = dm(i0, 1);
    i2 = r0;
    r3 = 0;                       /* the mask being built      */
    r4 = 1;                       /* bit for source aux 1      */
    lcntr = AUXMTX_N, do .amp_rq until lce;
        r5 = dm(i2, 1);
        r5 = pass r5;
        if ne r3 = r3 or r4;
