    i1 = _auxmtx_prev;
    r3 = 0;
    r9 = AUXMTX_N;
.amp_chg:
    r0 = dm(i0, 1);
    r1 = dm(i1, 1);
    r0 = r0 xor r1;
    r3 = r3 or r0;
    r9 = r9 - 1;
    if ne jump (pc, .amp_chg);
    r3 = pass r3;
    if eq rts;

    /* ---- 4: rebuild the closure, from nothing, in a fixed order ----
