    i1 = _auxmtx_prev;
    lcntr = AUXMTX_N, do .amp_sv until lce;
        r0 = dm(i0, 1);
    .amp_sv:
        dm(i1, 1) = r0;
    i1 = _auxmtx_live;
    i2 = _auxmtx_reach;
    r0 = 0;
    r1 = 1;
    lcntr = AUXMTX_N, do .amp_ini until lce;
        dm(i1, 1) = r0;
        dm(i2, 1) = r1;
    .amp_ini:
        r1 = lshift r1 by 1;

    i0 = _auxmtx_req;
    i1 = _auxmtx_live;
    i2 = _auxmtx_reach;
    r9 = AUXMTX_N;                /* destination bus j         */
.amp_j:
    r0 = dm(i0, 1);               /* req[j]                    */
    r1 = 0;                       /* live[j], being built      */
    r2 = 1;                       /* bit for source aux i      */
    r8 = AUXMTX_N;                /* source aux i              */
