    r7 = r6 and r2;
    if ne r6 = r6 or r4;
    dm(i4, 1) = r6;
    r5 = r5 - 1;
    if ne jump (pc, .amp_u);
.amp_inext:
    r2 = lshift r2 by 1;
    r8 = r8 - 1;
    if ne jump (pc, .amp_i);
    dm(i1, 1) = r1;
    modify(i2, 1);
    r9 = r9 - 1;
    if ne jump (pc, .amp_j);

